const groups={},tests=[];let lines=[];const test=(name,run)=>tests.push({name,run});const log=(...args)=>lines.push(args.join(' '));async function runTests(){for(const {name,run}of tests){if(CASE&&name!==CASE)continue;lines=[];try{await run()}catch(e){log('ERROR',e.name,e.message)}groups[name]=lines.slice()}return groups}const attempt=fn=>{try{const v=fn();return v===undefined?'ok':v}catch(e){return e.name}};

test('base-request-constructor',()=>{const b=document.createElement('base');b.href='/nested/';document.head.append(b);log('request',new URL(new Request('child').url).pathname);b.href='/changed/';log('changed',new URL(new Request('child').url).pathname)});
test('base-anchor-reflection',()=>{const b=document.createElement('base');b.href='/nested/';document.head.append(b);const a=document.createElement('a');a.href='child';log('anchor',new URL(a.href,document.URL).pathname);b.href='/changed/';log('changed',new URL(a.href,document.URL).pathname)});
test('base-script-reflection',()=>{const b=document.createElement('base');b.href='/nested/';document.head.append(b);const s=document.createElement('script');s.src='child.js';log('script',new URL(s.src,document.URL).pathname);b.href='/changed/';log('changed',new URL(s.src,document.URL).pathname)});
