test('url-empty-attributes',()=>{const b=document.createElement('base');b.href='/nested/';document.head.append(b);for(const tag of ['a','script','link','form','button','input']){const e=document.createElement(tag),key=tag==='a'||tag==='link'?'href':tag==='script'?'src':tag==='form'?'action':'formAction';log(tag,'missing',e[key]===''?'empty':new URL(e[key],document.URL).pathname);e[key]='';log(tag,'empty',new URL(e[key],document.URL).pathname)}});
