test('url-reflection-private',()=>{const b=document.createElement('base');b.href='/nested/';document.head.append(b);const a=document.createElement('a');a.setAttribute('href','child');let calls=0;for(const key of ['ownerDocument','baseURI'])Object.defineProperty(a,key,{get(){calls++;throw Error('author getter')},configurable:true});a.getAttribute=()=>{calls++;throw Error('author attr')};log('private',new URL(a.href).pathname,calls);a.href='next';log('set',new URL(a.href).pathname,calls)});
